let currentTraceId = null;

async function handler(req) {
  currentTraceId = req.id;            // 'A' for req A, 'B' for req B
  await db.query('SELECT 1');         // yields to the event loop
  logger.info({ traceId: currentTraceId }, 'done');
}

// A arrives, then B arrives before A's await resolves.
What traceId does A's final log line show? What about B's?

